<?php require_once __DIR__ . '/inc_app.php'; require_login(); if (!is_admin()) redirect('index.php');
if ($_SERVER['REQUEST_METHOD']==='POST') { if (isset($_POST['save'])) execute_query('UPDATE transactions SET status=? WHERE id=?', 'si', [$_POST['status'], (int)$_POST['id']]); if (isset($_POST['delete'])) execute_query('DELETE FROM transactions WHERE id=?', 'i', [(int)$_POST['id']]); redirect('admin-transactions.php'); }
$rows = fetch_all('SELECT t.*,s.title service FROM transactions t JOIN orders o ON o.id=t.order_id JOIN services s ON s.id=o.service_id ORDER BY t.id DESC'); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Транзакции админ</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php include 'admin_header.php'; ?><div class="container py-4"><h1>Транзакции</h1><table class="table table-sm"><tr><th>ID</th><th>Услуга</th><th>Сумма</th><th>Способ</th><th>Статус</th><th></th></tr><?php foreach($rows as $r): ?><tr><form method="post"><td><?= (int)$r['id']; ?><input type="hidden" name="id" value="<?= (int)$r['id']; ?>"></td><td><?= h($r['service']); ?></td><td><?= (int)$r['amount']; ?></td><td><?= h($r['method']); ?></td><td><input class="form-control form-control-sm" name="status" value="<?= h($r['status']); ?>"></td><td class="d-flex gap-1"><button class="btn btn-sm btn-outline-dark" name="save">Сохранить</button><button class="btn btn-sm btn-outline-danger" name="delete">Удалить</button></td></form></tr><?php endforeach; ?></table></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
